    @Test
    void terminalStatesAreIdempotentAndCannotBeResurrected() {
        // 驳回为终态：重复驳回幂等成功，迟到审批不得复活
        service.apply(req("R-REJ", "BERTH-1", D + "06:00:00Z", D + "08:00:00Z", "5", 0));
