        service.approve("C");

        // 改期 A2 [08:00,12:00)：与原窗口 A 自身重叠不算冲突，可获批
        ApplyWindowRequest reschedule = new ApplyWindowRequest("A2", "MV-A", "BERTH-1",
                Instant.parse(D + "08:00:00Z"), Instant.parse(D + "12:00:00Z"),
