        assertThat(a.assignedPilots()).containsExactly("PILOT-1", "PILOT-2");

        // B 与 A 时段重叠且需 2 名：仅剩 1 名可用，审批失败
        service.apply(req("B", "BERTH-2", D + "08:00:00Z", D + "12:00:00Z", "5", 2));
